import java.util.*;

class Solution {
    public long[] runningSum(int[] nums) {
        long[] res = new long[nums.length];
        long sum = 0;                        // can reach 1e14
        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];                  // prefix[i] = prefix[i-1] + nums[i]
            res[i] = sum;
        }
        return res;
    }
}

